# Fix the typo and continue
def is_hsymmetric(grid):
    h, w = grid.shape
    return np.array_equal(grid[:, :], grid[::-1, :])

def is_vsymmetric(grid):
    h, w = grid.shape
    return np.array_equal(grid[:, :], grid[:, ::-1])

print(f"Horizontal symmetric (top-bottom mirror): {is_hsymmetric(grid)}")
print(f"Vertical symmetric (left-right mirror): {is_vsymmetric(grid)}")

# Let's look at specific patterns more carefully
# Maybe there are smaller repeating units

# Check if there's a 6x6 or similar block structure
h, w = grid.shape

for block_size in [3, 4, 6, 8, 12]:
    if h % block_size == 0 and w % block_size == 0:
        print(f"\nChecking {block_size}x{block_size} blocks...")

        # Count how unique each block is
        blocks = []
        for i in range(0, h, block_size):
            for j in range(0, w, block_size):
                blocks.append(tuple(grid[i:i+block_size, j:j+block_size].flatten()))

        unique_blocks = len(set(blocks))
        total_blocks = len(blocks)
        ratio = unique_blocks / total_blocks

        print(f"  Unique blocks: {unique_blocks}/{total_blocks} ({100*ratio:.0f}%)")

# Look at rows and columns for patterns
h, w = grid.shape

print("First 6 rows:")
for i in range(6):
    print(f"Row {i}: {grid[i]}")

print("\nLast 6 rows:")
for i in range(h-6, h):
    print(f"Row {i}: {grid[i]}")

# Check if certain rows are repeats
unique_rows = {}
for i in range(h):
    tup = tuple(grid[i])
    if tup not in unique_rows:
        unique_rows[tup] = []
    unique_rows[tup].append(i)

print(f"\nUnique row count: {len(unique_rows)}")
if len(unique_rows) < h:
    print("Duplicate rows found!")
    for tup, indices in unique_rows.items():
        if len(indices) > 1:
            print(f"  Row type {tup[:5]}... appears at: {indices}")

